/* Alfred University AU-ESET 301 v16.1 — instructional completion layer.
   This file enriches the existing v16 curriculum without replacing saved IDs,
   dates, progress records, or Cloud Sync structures. */
(() => {
  const C = window.ALFRED_CURRICULUM;
  const A = window.ALFRED_ASSESSMENT;
  if (!C || !A || !Array.isArray(C.modules)) return;

  const home = {
    '1':1,'2':2,'3':7,'4':2,'5':12,'6':13,'7':19,'8':3,'9':4,'10':9,
    '11':10,'12':18,'13':11,'15':14,'16':17,'17':19,'18':19,'19':20,'20':20,'21':28,
    C1:1,C2:13,C3:3,C4:12,C5:13,C6:14,C7:15,C8:16,C9:18,C10:27,C11:28,C12:22,C13:30
  };

  const topics = {
    1:{name:'electrical quantities and low-voltage safety',core:'Voltage is an energy difference between two referenced points; current is charge flow through a complete path; resistance relates the two; and power is the rate of energy conversion. A safe technician predicts all four, establishes polarity and a reference node, checks component ratings, and defines a stop condition before energizing. Shock, fire, stored energy, ESD, meter-jack, and short-circuit hazards are separate mechanisms and require controls appropriate to the actual source.',math:'Use V = IR and P = VI, with P = I²R and P = V²/R as derived forms. Name the known and unknown quantities, convert prefixes, retain units through substitution, estimate the expected order of magnitude, then check power and tolerance. A mathematically correct current is not an acceptable design if it exceeds a source, conductor, meter, LED, or resistor rating.',visual:'Draw the source, protective/current-limiting element, load, return path, polarity, and reference node. Mark voltages across elements and current through the loop. Before touching a meter, add the planned meter symbol in parallel for voltage or in series for current. This diagram makes a misplaced current lead visible before it becomes a short.',evidence:'A defensible result includes the pre-power inspection, calculated prediction, supply limit, actual route, meter mode/jack/placement, measured values, percent difference, stop-condition check, and one sentence explaining any mismatch.',faults:['confusing voltage with current','using kilo or milli as though it were a unitless label','continuing after a hazard or unexpected current appears']},
    2:{name:'DC networks, KCL, KVL, and divider behavior',core:'Series elements share current; parallel branches share voltage. Kirchhoff’s current law expresses charge conservation at a node, while Kirchhoff’s voltage law expresses energy conservation around a closed loop. Equivalent resistance is a modeling tool, not a claim that the physical network vanished. A divider produces its expected ratio only when the connected load does not materially change the lower-leg resistance.',math:'Reduce only combinations that are truly series or parallel. For a divider, Vout = Vin·Rbottom/(Rtop+Rbottom); with a load, replace Rbottom by Rbottom || Rload before recalculating. Check that branch currents sum at nodes, signed drops sum around loops, and total source power is consistent with load dissipation.',visual:'Choose ground, label every node, draw current arrows, and write an expected voltage beside each test point. For troubleshooting, compare adjacent nodes along the energy path. The first unexpected boundary usually separates the working portion from the fault region more efficiently than random component replacement.',evidence:'Keep the schematic, equations, predicted node table, actual table, instrument reference, and the fault-isolation sequence. State which measurement ruled out each competing hypothesis.',faults:['treating components that share only one node as series','using the unloaded divider equation after adding a heavy load','changing several parts before locating the first incorrect node']},
    3:{name:'measurement instruments and uncertainty',core:'A measurement is a comparison made by a particular instrument under stated conditions. DMM voltage, current, resistance, continuity, diode, and frequency modes connect differently. A bench supply regulates voltage or current depending on the load and limit. An oscilloscope shows voltage versus time, but probe attenuation, coupling, bandwidth, reference location, trigger, sample rate, and loading shape what appears.',math:'Predict magnitude and frequency before choosing range or time base. Report units, polarity, reference node, AC/DC coupling, probe factor, and relevant tolerance. Resolution is the smallest displayed step; accuracy describes closeness to the true value. Repeatability, lead resistance, probe capacitance, bandwidth, and circuit tolerance can explain disagreement without making every difference a fault.',visual:'Use a measurement plan table: quantity, expected value, instrument, connection, settings, reference, acceptable range, stop condition. On a scope sketch, label vertical scale, time scale, zero/reference, trigger level, amplitude convention, period, and frequency.',evidence:'Save settings with the value: a screenshot or photo, probe/reference point, circuit revision, expected range, repeated result, uncertainty source, and interpretation. A number without context is not reproducible evidence.',faults:['placing a current-configured meter across a source','reading peak-to-peak as peak or RMS','trusting an autoranged display without checking units, probe factor, or loading']},
    4:{name:'AC waveforms and energy storage',core:'A periodic waveform is described by amplitude, period, frequency, offset, phase, and shape. Capacitor voltage cannot change instantaneously in the ideal model because that would require infinite current; inductor current cannot change instantaneously because that would require infinite voltage. Those constraints create transient behavior and make component response depend on both time and frequency.',math:'Use f = 1/T, Vrms = Vpk/√2 for a sine wave, XC = 1/(2πfC), XL = 2πfL, and τ = RC or L/R for first-order circuits. State waveform assumptions; RMS shortcuts for sine waves do not automatically apply to every shape. Check limiting cases: a capacitor tends toward open-circuit behavior at DC and lower impedance as frequency rises.',visual:'Sketch source and response on the same axes, label zero, peak, period, phase, initial value, final value, and one time constant. A Bode-style magnitude sketch should show the pass region, corner, and roll-off direction even when precise plotting is not required.',evidence:'Record the source settings, predicted amplitude/phase/time constant, capture settings, cursors, measured result, and why the result is physically reasonable.',faults:['using 1/f with milliseconds and forgetting unit conversion','assuming capacitor current or inductor voltage is always zero','describing a waveform without saying peak, peak-to-peak, RMS, offset, or reference']},
    5:{name:'cumulative foundation repair and fault isolation',core:'Mastery means selecting the right model when the topic is not announced. Start from the symptom and known-good behavior, create at least two plausible hypotheses, and choose a safe measurement whose possible outcomes separate them. A wrong answer is useful only after the underlying error mechanism is named and a changed example is solved correctly.',math:'Recompute missed items from first principles: identify quantities, units, topology, governing law, expected direction, and reasonable range. Do not repair by memorizing the option letter. For a practical fault, preserve the baseline and change one variable at a time.',visual:'Use a fault tree or hypothesis table with columns for hypothesis, predicted signature, discriminating test, result, and disposition. The table should shrink uncertainty after every measurement.',evidence:'Retain the first attempt, correction in your own words, fresh transfer item, baseline/fault/retest measurements, and a brief teach-back. Green requires both the knowledge target and practical evidence.',faults:['repeating the same form until choices look familiar','replacing the first plausible component','counting a correct calculation without safe measurement or interpretation']},
    6:{name:'reactance, impedance, filters, resonance, and transformers',core:'Resistance dissipates energy; ideal capacitance and inductance store and return energy. Their opposition in AC is frequency dependent and includes phase, so impedance must retain both magnitude and relationship between voltage and current. Resonance occurs when inductive and capacitive effects balance; it can create useful selectivity and unexpectedly large circulating voltage or current.',math:'Use XC = 1/(2πfC), XL = 2πfL, and combine impedance according to topology. For ideal resonance, f0 = 1/(2π√LC). For transformers, relate turns, voltage, and current while respecting power loss, insulation, frequency, core saturation, and loading. Always check behavior as frequency approaches zero or becomes large.',visual:'Draw phasor direction or a labeled qualitative phase diagram, a frequency-response curve, and the transformer core/winding relationship. Mark which variables rise, fall, or peak as frequency changes.',evidence:'Show component values and tolerances, calculated corner/resonant behavior, source and probe loading, a frequency sweep or selected points, phase/amplitude evidence, and a discrepancy explanation.',faults:['adding reactance magnitudes while ignoring phase','treating resonance as unlimited gain in a real lossy circuit','using a transformer ratio without checking frequency, loading, insulation, or core limits']},
    7:{name:'components, magnetism, relays, motors, and generators',core:'A technician identifies a component by symbol, construction, function, ratings, polarity or pinout, expected behavior, and common failure mode—not by appearance alone. Resistor types, markings, capacitors, inductors, transformers, relays, motors, generators, sensors, switches, and protection devices each convert or constrain energy differently. Magnetic components store energy and can generate damaging turn-off voltage.',math:'Translate markings and color codes, calculate dissipation and tolerance, estimate coil current from resistance/voltage, and compare operating values with absolute maximum and recommended ratings. A flyback path must handle coil current and stored energy; a relay contact rating is separate from the coil rating.',visual:'Trace command energy through driver, coil, magnetic field, mechanical contact or motion, and load. Mark the turn-off current path. For a datasheet, locate pinout, operating range, absolute maximums, test conditions, package, and derating information.',evidence:'Save identification evidence, datasheet excerpts with exact limits, calculations, measured coil/winding values, driver/protection schematic, expected states, actual states, and fault symptoms.',faults:['choosing a substitute by package or nominal value alone','confusing relay coil ratings with contact ratings','opening an inductive current path without a safe suppression route']},
    8:{name:'diodes, BJTs, FETs, and controlled switching',core:'A semiconductor device is useful because terminal conditions control conduction. Diodes enforce polarity-dependent behavior; BJTs use base current to control collector current; MOSFETs use gate-source voltage to control a channel. Switching design requires a defined OFF state, adequate drive, load-current margin, power/thermal checks, voltage-transient control, and awareness that logic-level and threshold voltage are not the same.',math:'Use a piecewise diode model when appropriate, compute LED or base resistance, estimate BJT forced beta for saturation, and use RDS(on) conduction loss P≈I²R for a MOSFET. Compare VGS conditions, SOA, voltage/current limits, and thermal resistance to the real circuit, not only headline ratings.',visual:'Draw current paths for ON, OFF, and inductive turn-off states. Label BJT E/B/C or MOSFET G/D/S, body diode, gate/base resistor, pull resistor, load, clamp, supply, and controller reference.',evidence:'Include the device choice and datasheet conditions, drive calculation, load prediction, thermal/rating margin, waveform or measured states, deliberate safe fault, diagnosis, and corrected retest.',faults:['treating MOSFET threshold voltage as fully-on voltage','omitting a default pull resistor and leaving the control floating','testing an inductive load without a clamp or voltage-margin analysis']},
    9:{name:'power-supply blocks and bring-up',core:'A supply moves energy through functional blocks such as protection, conversion or rectification, filtering, regulation, feedback, and load distribution. Linear and switch-mode supplies create different waveforms and loss mechanisms. Troubleshooting proceeds from input toward output, stopping at the first block whose input is correct but output violates the expected relationship.',math:'Use diode-drop and ripple approximations only with their assumptions stated. Calculate load current, power, dissipation, capacitor ripple trend, dropout/headroom, and efficiency. Check startup, current limit, short protection, thermal margin, and the energy stored in capacitors before probing.',visual:'Draw a block diagram and expected waveform at each boundary: source, rectifier/switch node, filter, regulator/feedback, and output. Mark ground domains, isolation boundaries, and safe measurement references.',evidence:'Record power-off resistance, supply limit, staged rail measurements, startup/current behavior, ripple capture, load condition, fault signature, root cause, and normal-load retest.',faults:['probing an offline or non-isolated supply as though it were low-voltage ground referenced','replacing the regulator before proving its input and load','calling a rail good from DC voltage while ignoring ripple, startup, load, or current limit']},
    10:{name:'amplifiers, op-amps, gain, and loading',core:'An amplifier controls energy from its supply so an input signal produces a related output. Gain depends on topology, frequency, feedback, bias, loading, and headroom. Ideal op-amp rules are conditional approximations under negative feedback and linear operation; saturation, slew rate, common-mode range, output swing, bandwidth, noise, and stability constrain real behavior.',math:'Use Av = Vout/Vin and dB = 20 log10(Vout/Vin) for voltage ratios under consistent impedance assumptions. Derive inverting and non-inverting closed-loop gain, then verify supply rails, input common-mode range, output swing/current, gain-bandwidth, and component tolerance.',visual:'Trace the signal through bias/coupling, input network, active stage, feedback, load, and supplies. Sketch expected input/output with amplitude, phase, offset, clipping boundary, and measurement points.',evidence:'Keep the schematic, gain prediction, DC operating points, source/load conditions, frequency test, input/output capture, observed distortion or fault, diagnosis, and corrected transfer.',faults:['using virtual short rules after the output has saturated','computing gain without checking rail headroom or bandwidth','measuring an unloaded output and assuming the same result under the real load']},
    11:{name:'number systems and digital logic',core:'Digital circuits map voltage ranges to logical states, then implement Boolean decisions and stored state. Binary and hexadecimal are compact representations of bit patterns, not different physical values. Combinational outputs depend on present inputs; sequential circuits also depend on clocking and prior state. Real inputs need defined levels, timing margin, pull resistors, and often debounce or synchronization.',math:'Convert by positional weights or grouped binary nibbles, apply Boolean identities or truth tables, and track bit width, signedness, masks, and overflow. Timing analysis must distinguish period, frequency, propagation delay, setup/hold, pulse width, and duty cycle.',visual:'Use truth tables, timing diagrams, state tables, and gate/register blocks. Mark thresholds, clock edge, stable windows, propagation delay, and unknown/floating regions. A timing sketch often exposes an assumption that a static truth table hides.',evidence:'Save conversions, truth/state table, logic implementation, measured or simulated timing, pull/debounce choice, expected transitions, injected input fault, and verification.',faults:['treating a floating input as a reliable zero','mixing decimal digits with hexadecimal values','ignoring timing and assuming every gate or register changes simultaneously']},
    12:{name:'ESD, soldering, rework, and traceability',core:'Workmanship controls heat, cleanliness, mechanical stress, contamination, electrostatic energy, and traceability. A good joint forms a reliable metallurgical and mechanical connection without damaging pad, lead, insulation, or neighboring parts. Desoldering braid, suction, flux, temperature, dwell time, pad-repair limits, SMT/BGA recognition, and inspection each address different failure risks. Virtual preparation cannot establish physical hand skill.',math:'Use component and process limits rather than “hotter is better.” Where quantified, record tip temperature, dwell, conductor gauge, strip length, continuity/resistance, and acceptance limits. ESD controls must be verified for the approved de-energized workstation; never connect a wrist strap to an energized hazard.',visual:'Document before/after closeups, joint/pad geometry, polarity, reference designator, conductor strain relief, and harness pinout. A change log ties the physical revision to the schematic, test procedure, and result.',evidence:'Physical claims require actual photos, inspection, continuity, rework result, and process notes. Simulation or videos can prove planning and recognition only. Commit the change, reason, artifact, test result, and limitation.',faults:['adding heat until a lifted pad makes the original defect worse','using ESD equipment in an unverified or energized situation','claiming soldering proficiency from a virtual route']},
    13:{name:'schematics, datasheets, signal flow, and root cause',core:'A block diagram explains function, a schematic explains electrical relationships, a wiring diagram explains physical connections, and a layout shows physical implementation. Reference designators, net names, connector pins, power domains, and signal direction make these representations cross-checkable. A datasheet states behavior under specific conditions; typical values are not guaranteed limits.',math:'Turn ratings and transfer relationships into expected node ranges. Include tolerance, loading, logic threshold, bandwidth, timing, and test conditions. A root-cause test should maximize information: predict distinct outcomes for competing causes before measuring.',visual:'Annotate the signal path from source through conditioning, conversion, processing, interface, and output. Add expected values at boundaries and a hypothesis table. Mark where the first bad boundary would implicate upstream or downstream blocks.',evidence:'Preserve document revision, annotated diagram, expected-value table, competing hypotheses, selected test and why, measured evidence, cause, corrective action, and regression test.',faults:['confusing a typical curve with a guaranteed specification','replacing a component because it is near the symptom','using a layout or wiring view as though it communicates every schematic relationship']},
    14:{name:'computer architecture and C fundamentals',core:'A program moves through preprocessing, compilation, assembly, linking, loading, and execution. CPU, registers, memory, buses, peripherals, storage, and I/O cooperate to transform instructions and data into physical effects. In C, types determine representation and operations; scope and lifetime determine where an object can be named and how long it exists; functions, control flow, arrays, strings, structs, enums, and pointers organize behavior and data.',math:'Track integer width, signedness, ranges, index bounds, address versus value, and unit conversions. Predict each expression before running it. Compiler warnings, return codes, tests, and a debugger are measurement instruments for software; they do not replace understanding of the machine state.',visual:'Draw source-to-executable stages, a memory map with code/static/stack/heap, and data flow through functions. For a pointer, draw the object, address, pointer variable, and dereference rather than treating the asterisk as magic.',evidence:'Save source, build command/tool version, warnings, tests, expected output, actual output, debugger observation, deliberate defect, root cause, correction, and README explanation.',faults:['copying code that runs without explaining data flow','confusing an address with the value stored there','ignoring compiler warnings or array bounds because one test happened to pass']},
    15:{name:'embedded C, bit operations, state machines, and timing',core:'Embedded software shares responsibility with hardware timing, registers, interrupts, and external state. Masks isolate bit fields; volatile tells the compiler an object may change outside ordinary flow but does not make access atomic or thread safe. A nonblocking finite-state machine makes current state, inputs, transition conditions, outputs, timeouts, and error recovery explicit.',math:'Derive masks with shifts, show read-modify-write consequences, use unsigned fixed-width types for registers, and compare elapsed time safely. Separate configuration constants from live state. Compute timing budgets and prove that polling or blocking delays do not hide required events.',visual:'Draw a state diagram with every transition condition and safe default; add a timing line for inputs, deadlines, and outputs. Sketch register bits with reserved fields and write semantics taken from the reference manual.',evidence:'Keep the state diagram, interface contract, register/mask reasoning, test cases including timeout/error states, code, trace/log, injected fault, correction, and retest.',faults:['using volatile as a universal concurrency fix','setting a register bit without preserving required neighboring bits','blocking in one state until the system misses other inputs or deadlines']},
    16:{name:'STM32 configuration, GPIO, clocks, and SWD',core:'MCU bring-up is a chain: known power and reset, correct target/board, clock and pin configuration, successful build, programmed image, verified reset/program flow, and observable GPIO or diagnostic behavior. SWD provides controlled access to core state, memory, registers, breakpoints, and stepping. Each layer should be proven before a peripheral-rich application is added.',math:'Check logic voltage, current limits, clock source/frequency, prescalers, GPIO mode/pull/speed, pin multiplexing, and timing. Read the schematic, board manual, datasheet, and reference manual at their appropriate abstraction levels. A build success says nothing about power, pin routing, or physical signal integrity.',visual:'Create a bring-up ladder and pin map: power/reset → debugger → clock → GPIO → peripheral. Mark board connector pin, MCU port/pin, alternate function, voltage domain, and observable test point.',evidence:'Record board/revision, IDE/toolchain, configuration, clean build, flash verification, SWD breakpoint/register view, measured GPIO or logic state, known-good tag, recovery path, fault and retest.',faults:['changing clock, pin map, and application code simultaneously','assuming the silkscreen name equals the MCU port name','calling flashing successful without proving the new image executed']},
    17:{name:'UART and Python serial control',core:'UART frames asynchronous bytes with start, data, optional parity, and stop bits. Both ends must agree on baud, framing, voltage levels, polarity, and reference. Transported bytes are not yet a trustworthy message: the application must define encoding, framing, length, delimiters or checks, timeout, malformed input behavior, and recovery. Python can turn the stream into a repeatable timestamped test record.',math:'Relate baud to bit time and estimate frame time including overhead. Distinguish bits, bytes, characters, payload rate, buffer length, and timeout. Verify port identity and settings rather than assuming the first enumerated device is correct.',visual:'Draw TX↔RX and common reference, then a timing frame and software pipeline: port → bytes → buffer/framer → parser → validated record. Mark where electrical, framing, transport, parsing, and application faults appear.',evidence:'Save wiring/levels, settings, transmitted stimulus, raw bytes, parsed values, timestamps, timeout/error handling, malformed-message test, correction, and repeatable run instructions.',faults:['connecting incompatible voltage levels or omitting the common reference','debugging parsing before proving raw bytes and frame settings','treating decode errors or timeouts as valid zero data']},
    18:{name:'I²C, SPI, logic analysis, sensors, and actuators',core:'I²C shares open-drain SDA/SCL lines with pull-ups, addressing, START/STOP, ACK/NACK, and register transactions. SPI uses controller-driven clock, chip select, MOSI/MISO, and mode-dependent sampling. Electrical requirements, pin multiplexing, bus timing, register sequence, units, and device state must all agree. A decoder label is evidence only after thresholds, sample rate, channel mapping, and raw waveform are credible.',math:'Calculate or bound pull-up behavior, logic levels, clock rate, transfer length, conversion scaling, and timing margins from the datasheet. Distinguish address from register, byte order, signedness, raw code from engineering unit, and nominal from tolerance.',visual:'Draw physical wiring, pull-ups or chip-select, shared reference, voltage domains, and the exact transaction. Add a timing diagram with START/address/RW/ACK/data/STOP or CS/clock/MOSI/MISO and CPOL/CPHA.',evidence:'Retain datasheet trace, pin map, configuration/build/flash, SWD proof, UART log, raw and decoded capture, known stimulus, converted value, safe fault, diagnosis, correction, nominal/recovery retest, and physical/virtual label.',faults:['adding push-pull contention to an open-drain bus','trusting the protocol decoder without checking the raw waveform','changing address, wiring, and firmware together after a NACK']},
    19:{name:'cabling, audio/video paths, and optical electronics',core:'Cables and connectors carry power, analog, digital, RF, or optical energy with constraints on pinout, impedance, shielding, bandwidth, direction, bend radius, termination, and environment. Audio/video systems are signal chains with conversion, amplification, display/transducer, and interface blocks. Optical devices include emitters, detectors, photoresistors, photovoltaic devices, opto-isolators, fiber sources/receivers, displays, and seven-segment/LCD/OLED technologies.',math:'Use continuity and resistance only where appropriate and de-energized; do not infer high-frequency integrity from DC continuity alone. Relate signal level, attenuation, bandwidth, impedance, optical power, wavelength, and conversion role at the level required by the component/system.',visual:'Trace source → connector/cable → conversion/processing → output. Draw pinout end views explicitly, label shield/reference and direction, and identify optical isolation or display drive boundaries.',evidence:'Save identification, pinout/source, inspection criteria, continuity or signal test, known-good substitution, fault signature, corrected termination, route limitation, and before/after evidence.',faults:['assuming a cable is compatible because the connector fits','mirroring a connector pinout by viewing the wrong end','claiming signal integrity, optical power, or physical termination skill from continuity or simulation alone']},
    20:{name:'RF, telecommunications, spectrum, and procedures',core:'Communication systems represent information, modulate or encode it, move it through a channel/feedline/antenna, receive it, and recover it. Frequency, bandwidth, wavelength, impedance, attenuation, noise, gain, and modulation describe different properties. Safe practice matters: this course uses receive-only, low-power, simulated, or instrument-safe paths and does not authorize transmitter, tower, mains, or exposure work.',math:'Use λ = c/f, ratio and decibel relationships under stated conditions, and frequency/time conversions. Treat impedance matching, reflected energy, loss, and measurement bandwidth as system constraints. A spectrum display shows power or amplitude versus frequency; it does not directly show time-domain shape or protocol meaning.',visual:'Draw information source → modulation/encoding → transmitter → feedline/antenna/channel → receiver → demodulation/decoding → output. Mark safe test points and the measurement domain at each block.',evidence:'Include source/settings, safe scope, expected carrier/bandwidth, capture, marker/reference bandwidth, interpretation, fault or mismatch hypothesis, handoff note, and limitation.',faults:['confusing signal frequency with data rate or modulation bandwidth','using dB arithmetic without identifying gain, loss, power, or voltage assumptions','transmitting or probing outside the approved low-energy/non-radiating scope']},
    21:{name:'interleaved CETa retrieval and technician decisions',core:'Interleaving removes the chapter label that normally hints at the method. The learner must first identify the domain, relevant physical model, required unit or representation, safety boundary, and evidence needed. Retrieval is strongest when the answer is produced before notes and then corrected from a governing source.',math:'Build a compact formula map that names variables, units, assumptions, and limiting behavior. Work mixed calculations in a different order from study, estimate before calculating, and use dimensional and power/energy checks to reject impossible results.',visual:'Use a one-page decision map linking symptom or question type to model, formula, diagram, instrument, and verification. Keep weak rows visible without turning every topic into a giant undifferentiated review list.',evidence:'Preserve timed form results, exact competency IDs, error mechanism, corrected reasoning, fresh changed example, and later retrieval result. Repeated recognition of the same item is weaker than transfer.',faults:['choosing a formula because its symbols resemble the question','reviewing only comfortable domains','equating one high score on familiar items with durable readiness']},
    22:{name:'targeted CETa repair and project requirements',core:'Repair targets causes, not chapters. A missed competency is classified as knowledge gap, model-selection error, unit/calculation error, diagram-reading error, unsafe procedure, or distractor reasoning. In parallel, a project requirement converts a need into a measurable condition with method, tolerance, and pass/fail rule before the design is built.',math:'For each weak calculation, create a changed-number example and an estimation check. For each project requirement, state quantity, condition, limit, method, sample count where relevant, and acceptance criterion. Avoid untestable words such as reliable, fast, or accurate without a definition.',visual:'Maintain two linked tables: competency → error → repair → retest, and need → requirement → design choice → test → evidence. The project trace should show why each measurement exists.',evidence:'Keep current practice evidence, correction, fresh transfer, requirements, architecture, BOM, pin map, interface plan, risks, verification matrix, design review decisions, and revision.',faults:['rereading a whole chapter without addressing the exact miss','writing a feature wish as though it were a measurable requirement','building first and inventing pass criteria after seeing the result']},
    23:{name:'CETa readiness and reproducible project setup',core:'Readiness is a decision based on current independent evidence, not confidence alone. Alfred requires two separate current comprehensive CETa practice runs at or above 85%; ETA’s published passing score remains a distinct official rule and Alfred cannot guarantee the exam. Project work begins from a reproducible baseline with recorded tools, versions, target, clean build, known-good tag, and recovery path.',math:'Compare score by domain and error type, not only overall percent. Confirm each full-length run meets the form and time conditions and is not a duplicate memorization exercise. For the project, record hashes/versions and verify that another clean workspace can reproduce the build.',visual:'Use a readiness gate with two independent score records and a project-baseline chain: repository → environment → configuration → build → flash/run → rollback.',evidence:'Retain both full-run results, weak-row corrections, official fact check, exam decision, repository layout, dependency/tool versions, build output, baseline tag, and recovery test.',faults:['confusing Alfred’s 85% readiness rule with ETA’s official passing requirement','counting two attempts on the same memorized form as independent evidence','starting hardware changes before a known-good software/configuration baseline exists']},
    24:{name:'safe staged hardware bring-up',core:'First power is a controlled experiment. Inspect assembly and polarity, verify rail-to-ground resistance/continuity, separate loads where possible, set a conservative current limit, energize one domain, compare current and voltage with predictions, and stop at the first violated expectation. A known-good baseline makes later faults diagnosable.',math:'Estimate expected rail current and tolerance from active blocks, regulator loss, load states, and measurement uncertainty. Define acceptable voltage/current windows and startup behavior before power is applied.',visual:'Create a power tree with source, protection, regulators, rails, loads, enable/reset, and test points. Number the bring-up order and mark the observation that authorizes the next step.',evidence:'Save inspection, resistance checks, current limit, staged rail/current table, thermal observation, scope/DMM settings, first fault boundary, correction, baseline revision, and retest.',faults:['powering every subsystem at once','raising the current limit to make a faulty board stay on','continuing bring-up after the first unexplained rail or current result']},
    25:{name:'sensor and interface vertical-slice integration',core:'A vertical slice proves one complete path from known physical or simulated stimulus through sensor, electrical interface, transaction, driver, conversion, application, and observable output. Integration starts from datasheet conditions and an already proven bus, then adds one layer at a time with raw values visible before abstraction hides them.',math:'Convert raw codes with reference, scale, signedness, byte order, offset, and units. Define plausible range, tolerance, update rate, timeout, and fault indication. Compare a known stimulus with the converted result.',visual:'Draw stimulus → sensor → pins/bus → driver → raw register → conversion → application/output, with a test point at each boundary and the expected representation.',evidence:'Keep datasheet trace, wiring/pin map, transaction capture, raw code, conversion math, known stimulus, output, disconnect/wrong-address fault, diagnosis, recovery, and regression test.',faults:['debugging converted values before proving device identity and raw registers','hiding errors behind a default zero','adding multiple sensors/features before one slice is repeatable']},
    26:{name:'firmware architecture and diagnostic boundaries',core:'Maintainable firmware separates hardware access, interface/service behavior, application state, diagnostics, configuration, and recovery. Each layer has an explicit contract, testable inputs/outputs, error handling, and a way to observe state. The goal is not abstraction for its own sake; it is to localize failures and keep changes from producing invisible side effects.',math:'Track timing, buffer bounds, state transitions, return/error codes, retries, and resource limits. Define invariants and timeout values. Tests should cover nominal, boundary, invalid, timeout, reset, and recovery behavior.',visual:'Draw module dependencies and data flow. Arrows should show who calls whom, who owns state, where hardware registers are touched, and where diagnostic events cross the boundary.',evidence:'Save architecture diagram, interfaces, build/tests, diagnostic log, injected driver/application/configuration fault, localization reasoning, fix, regression result, and revision tag.',faults:['letting every module access hardware registers directly','printing logs without structured severity/context or error propagation','refactoring without a known-good regression test']},
    27:{name:'Python hardware-test automation and data integrity',core:'A hardware-test script is an executable procedure: identify and configure the device, apply a controlled command or stimulus, acquire raw data, validate framing/units, compare with explicit limits, record verdict and evidence, handle failures, and restore a safe state. Automation magnifies both good procedures and hidden assumptions.',math:'Represent limits with units and inclusive/exclusive boundaries, retain raw precision, and separate display rounding from pass/fail logic. Use timestamps and monotonic duration appropriately. Validate sample count, missing data, malformed messages, and repeatability.',visual:'Draw setup → command → acquisition → validation → calculation → limit check → record → cleanup. Include timeout/error branches, not only the happy path.',evidence:'Save script/version, configuration, DUT identity/revision, raw CSV/JSON, calculated values, limits, PASS/FAIL, logs, malformed/timeout test, rerun instructions, and known limitations.',faults:['treating a communication timeout as a passing zero','changing limits inside code without traceability','saving only PASS while discarding raw data and configuration']},
    28:{name:'fault injection, root cause, and technical reporting',core:'Controlled fault injection tests diagnostic quality and recovery without creating uncontrolled damage. Establish a known-good baseline, select one safe reversible fault, predict signatures at boundaries, inject only that variable, collect evidence, localize cause, correct it, retest nominal operation and recovery, and document what the test cannot prove.',math:'Use expected ranges, timing, tolerance, and before/after comparisons. Quantify the observation that distinguishes hypotheses. A report separates raw result, calculation, interpretation, cause, corrective action, and verification.',visual:'Use an evidence chain: requirement → setup → baseline → injected fault → expected signature → actual observation → diagnosis → correction → regression. Link figures and logs to exact claims.',evidence:'The report includes objective, revision/configuration, safety control, procedure, raw evidence, observations, reasoning, cause, corrective action, nominal/recovery retest, limitation, and traceability.',faults:['injecting several faults at once','calling the repaired symptom proof of root cause without regression','writing conclusions that cannot be traced to a figure, log, or measurement']},
    29:{name:'instrumentation, rework, harnesses, and role proof',core:'Role-proof work combines instrument discipline, physical workmanship, wiring/harness verification, and technical explanation. Each claimed skill must point to an artifact showing the setup, decision, result, fault, correction, and limitation. Physical soldering, crimping, probe handling, and harness work require physical evidence; planning or simulation is labeled honestly.',math:'Use pin-to-pin continuity/resistance, voltage/current/ripple/timing limits, conductor and connector ratings, and measurement uncertainty appropriate to the task. Compare actual evidence with a stated acceptance criterion.',visual:'Create a harness pinout/end view, annotated rework before/after, instrument connection diagram, and evidence index that maps resume claims to files.',evidence:'Keep photos, instrument captures/settings, wiring/pinout, continuity table, workmanship inspection, power-up checklist, fault/fix, test result, revision, and physical/virtual status.',faults:['making a broad skill claim from one unlabeled photo','mirroring connector pins or omitting revision','using a clean final result while hiding the diagnostic process that proves judgment']},
    30:{name:'portfolio, resume, interview defense, and retention',core:'An employer-facing artifact lets a reviewer understand the problem, requirements, design, implementation, measurements, failures, results, and limitations quickly. Resume bullets remain truthful and role specific. Interview explanations show personal reasoning: what changed, why a test was chosen, what evidence ruled causes in or out, and what would be improved next.',math:'Quantify only defensible outcomes: voltage/current/timing tolerance, test count, failure reduction, repeatability, or coverage. Do not invent business impact. Retain enough technical detail to defend every number.',visual:'Use a portfolio information hierarchy: one-sentence outcome, block diagram, key schematic/interface, evidence table, fault story, result, limitations, repository path. Prepare 90-second, two-minute, and five-minute explanations.',evidence:'Save targeted resume versions, portfolio index, project README, diagrams, evidence links, five technical stories, mock questions, corrections, role-fit checklist, and current CETa retrieval record.',faults:['listing tools without showing what was done with them','using inflated titles or unsupported metrics','targeting a role that abandons the hardware/electronics and continued-college constraints']},
    31:{name:'applications, feedback, and continuing mastery',core:'The application process is an evidence-and-feedback loop. Target legitimate permanent electronics, hardware test/validation, engineering-technician, integration, and embedded-adjacent roles that fit compensation, benefits, and continued college. Track requested skills and interview misses, rank repeated signals, repair the highest-value gap, and keep applying without restarting the entire curriculum.',math:'Track role family, required skill frequency, response stage, schedule/compensation constraints, and dated repair evidence. Use counts as signals, not guarantees; a small sample or one rejection does not justify abandoning the plan.',visual:'Map role target → tailored evidence → application → interview question → observed gap → focused repair → updated artifact. Keep CETa retention on a separate recurring lane.',evidence:'Maintain application log, tailored package, interview question/answer record, skill-gap backlog, dated repair artifact, portfolio revision, follow-up, and continuing retrieval schedule.',faults:['rewriting everything after each response','pausing all applications until optional perfection','accepting a role that does not meet the defined hardware, stability, school, or compensation gate']}
  };

  const cetaMethod = {
    '1':'Connect the named hazard to its physical consequence, choose the control that removes or reduces exposure, state the stop/escalation boundary, and distinguish recognition knowledge from authorization to perform hazardous work.',
    '2':'Define the electrical quantity physically, name its unit and relationship, predict direction or magnitude, calculate when applicable, and verify the result against conservation, ratings, and a safe measurement.',
    '3':'Identify the component by symbol, construction, function, polarity or pinout, ratings, normal behavior, failure signature, and substitution constraints; use the datasheet rather than appearance alone.',
    '4':'Redraw the topology, identify what is truly series or parallel, apply KCL/KVL and equivalent-resistance reasoning, predict nodes/branches, and check the solution with units and power.',
    '5':'Name the tool and controlled process, explain heat/force/ESD risks, identify acceptable and defective workmanship, inspect and electrically verify the result, and separate virtual recognition from physical proficiency.',
    '6':'Choose the correct representation—block, schematic, wiring, or layout—trace power and signal flow, interpret symbols/designators/nets, and convert the drawing into expected test-point behavior.',
    '7':'Identify media and connectors by purpose and constraints, verify pinout/termination/shield/reference, select a valid test, and avoid claiming high-frequency or optical integrity from a DC continuity result.',
    '8':'Name the measured quantity, choose instrument/mode/jack/range/reference, predict a safe reading, account for loading and uncertainty, interpret the observation, and preserve settings with the value.',
    '9':'Write the governing relationship, define every variable and unit, convert prefixes, solve step by step, estimate the order of magnitude, and interpret whether the result is physically and safely plausible.',
    '10':'Trace energy through protection, conversion, filtering, regulation, feedback, and load; predict each boundary waveform or rail and stop at the first violated relationship.',
    '11':'Identify topology, bias, feedback, gain, frequency, loading, and headroom; calculate with stated assumptions and distinguish linear operation from clipping, saturation, instability, or device limits.',
    '12':'Identify the electrical interface, direction, level, reference, timing/handshake, conversion, and failure boundary; verify raw signals before trusting interpreted data.',
    '13':'Represent values as bits, derive truth/state behavior, account for voltage thresholds and timing, and verify both static logic and transitions rather than relying on ideal symbols alone.',
    '15':'Trace instructions and data through CPU, registers, memory, buses, storage, and peripherals; distinguish representation, address, value, and hardware/software responsibility.',
    '16':'Identify the application/software layer, installation or configuration requirement, port/storage/network/backup behavior, security boundary, expected outcome, and recovery evidence.',
    '17':'Trace the audio/video signal chain from source through interface, processing, amplification/conversion, and output; distinguish signal format, level, bandwidth, and display/transducer function.',
    '18':'Explain how emission, detection, photovoltaic conversion, photoresistance, isolation, fiber transport, or display technology converts light and electricity, then select a valid observation or test.',
    '19':'Relate carrier, modulation, wavelength, bandwidth, feedline, antenna, channel, receiver, and spectrum while keeping the activity within approved receive-only or low-energy limits.',
    '20':'Trace information through telecommunications blocks, media, signaling, switching/multiplexing, and recovery; identify what representation changes and how a technician would verify the boundary.',
    '21':'Convert the requirement into a repeatable procedure with setup, revision, safety control, expected result, raw evidence, pass/fail rule, corrective action, verification, and technical handoff.'
  };
  const careerMethod = {
    C1:'Use a written pre-power and hazard log: identify condition, risk, stop action, corrective action, independent verification, and authorization before testing continues.',
    C2:'Trace design intent from schematic and datasheet to expected node, rating, tolerance, interface, and test point; distinguish guaranteed limits from typical examples.',
    C3:'Create a prediction-first measurement plan with quantity, instrument, connection, settings, reference, uncertainty, acceptance range, and interpretation.',
    C4:'Define the physical process and acceptance evidence for assembly, solder, rework, connector, or harness work; physical proficiency requires real workmanship and inspection.',
    C5:'Use competing hypotheses and one high-information test at a time; preserve baseline, cause, corrective action, and regression evidence.',
    C6:'Explain C data and control flow, types, scope/lifetime, functions, arrays/pointers, build stages, tests, and debugger observations without relying on copied code.',
    C7:'Connect bit operations, registers, memory, timing, interrupts/volatile limits, states, and error handling to the actual hardware behavior.',
    C8:'Prove the STM32 chain from power/reset and configuration through build, flash, SWD observation, GPIO behavior, recovery path, and documented baseline.',
    C9:'Prove interface electrical conditions and protocol transactions for UART, I²C, or SPI, including raw capture, parsing, controlled fault, recovery, and retest.',
    C10:'Turn a manual hardware check into a scripted procedure with configuration, command/stimulus, acquisition, validation, units, limits, raw data, verdict, error handling, and cleanup.',
    C11:'Write measurable requirements and execute nominal, boundary, error, and repeatability tests with traceable evidence and an honest limitation.',
    C12:'Make the work reproducible through revision control, engineering notes, procedures, diagrams, logs, reports, evidence links, and change rationale.',
    C13:'Convert real technical work into truthful role-specific evidence, defend the reasoning in an interview, and preserve the hardware/college/compensation gate.'
  };

  function assigned(row) {
    const candidates = C.modules.filter(m => (row.track === 'CETa' ? m.standards.ceta : m.standards.career).includes(row.code));
    const preferred = candidates.find(m => m.week === home[row.category]);
    return preferred || candidates[0] || C.modules.find(m => m.week === home[row.category]) || C.modules[0];
  }
  const rows = [...A.cetaStandards, ...A.careerStandards].map(row => ({...row,module:assigned(row)}));
  rows.forEach(item => {
    const key = item.track === 'CETa' ? 'ceta' : 'career';
    if (!item.module.standards[key].includes(item.code)) item.module.standards[key].push(item.code);
  });

  const allCoverage = [];
  function requirementTeaching(row, model) {
    const method = row.track === 'CETa' ? cetaMethod[row.category] : careerMethod[row.category];
    return `${row.code} — ${row.text}. Alfred treats the action verb as the performance target, not as a vocabulary prompt. ${method} In this week’s ${model.name} context, the learner must explain the mechanism in plain language, point to a circuit, instrument, diagram, code path, procedure, or workplace example where it appears, identify one tempting misconception or unsafe shortcut, and produce evidence that another person could inspect. A correct label without the cause-and-effect explanation does not complete this row.`;
  }

  C.modules.forEach(module => {
    const model = topics[module.week];
    module.lessons.forEach((lesson, lessonIndex) => {
      const trackRows = rows.filter(r => r.module.week === module.week && r.track === lesson.track);
      const cleanObjective = value => String(value || '').trim().replace(/[.?!]+$/,'');
      const cleanObjectives = lesson.objectives.map(cleanObjective);
      const firstObjective = cleanObjectives[0] || lesson.title;
      const objectiveText = cleanObjectives.join('. ') + '.';
      const sectionId = `W${String(module.week).padStart(2,'0')}-${lesson.track === 'CETa' ? 'CETA' : 'CAREER'}-DEPTH`;
      const clinic = trackRows.map(row => requirementTeaching(row, model));
      const trackPurpose = lesson.track === 'CETa'
        ? 'This is the certification-knowledge half of the week. It also supports technician decisions because the same quantities, parts, circuits, diagrams, and procedures appear on a real bench.'
        : 'This is the career-performance half of the week. It converts the theory into safe measurement, hardware/firmware implementation, troubleshooting, documentation, and evidence that can be defended to a technician or engineer.';
      lesson.instructionalDepth = {
        sectionId,
        purpose:`This lesson teaches ${lesson.title.toLowerCase()} within ${model.name}. ${trackPurpose} The finish line is not exposure: ${objectiveText} You should know why each step is valid, when its assumptions fail, and how the result would be verified.`,
        whatWhy:`The central model is this: ${model.core} This matters for CETa because it supplies the terminology, relationships, recognition, calculations, and safe decisions represented by the assigned competency rows. It matters for career transition because electronics and embedded work require a person to predict behavior, choose a discriminating test, interpret evidence, and communicate the boundary of what the evidence proves.`,
        prerequisites:`Activate the previous chain before continuing: identify the source and reference, state the expected direction of energy or data flow, name the units or representation at each boundary, and recall the stop condition. Reuse these specific objectives from the week: ${cleanObjectives.join('; ')}. If one of those statements cannot yet be explained, repair only that prerequisite rather than restarting the entire course.`,
        retrieval:`Without notes, draw the week’s core system from input to output and write three predictions: one normal value or state, one boundary or rating, and one symptom caused by a plausible fault. Then explain which previous law, instrument habit, programming idea, or troubleshooting rule supports each prediction. Check the answer against the lesson only after retrieval.`,
        teaching:[
          {title:'Build the physical and conceptual model',text:`${model.core} Read every noun as a quantity, component, state, or boundary and every verb as a relationship that can be demonstrated. Connect the model to the week’s objectives: ${objectiveText} Do not memorize disconnected definitions; ask what energy, charge, signal, data, or control state changes, what remains conserved, and what observation would prove the explanation.`},
          {title:'Calculate, represent, and sanity-check',text:`${model.math} Use the sequence Given → Find → Model → Assumptions → Units → Work → Result → Sanity check → Interpretation. For non-numerical topics, the equivalent is Input/state → rule → expected output/state → boundary condition → observable evidence. A result is incomplete until you can say whether its magnitude, sign, timing, state, rating, or behavior makes sense.`},
          {title:'Use the right representation',text:`${model.visual} Translate between words, equations, tables, schematics, block diagrams, timing plots, waveforms, code/data flow, and physical layout where applicable. Each representation answers a different question. Say what the drawing omits as well as what it shows, and label reference points, units, direction, revision, and assumptions so another person cannot silently interpret it differently.`},
          {title:'Turn understanding into inspectable evidence',text:`${model.evidence} Evidence must distinguish prediction from observation and raw result from interpretation. Name the actual virtual or physical route. A simulation can establish conceptual and analytical performance; it cannot establish tactile skill, real probe placement, solder quality, or physical assembly. Preserve one failure or misconception because the diagnosis and recovery show more judgment than a polished final state alone.`},
          {title:'Competency clinic — exact required rows',text:clinic.length ? clinic.join('\n\n') : `This retention lesson introduces no new official row. It deliberately returns to previously taught ${lesson.track} requirements through changed contexts. Use the objectives, worked example, cumulative application, and current assessment evidence to prove that the knowledge transfers beyond the original example.`}
        ],
        worked:{
          problem:`A learner must demonstrate “${firstObjective}” in a new ${model.name} scenario, but the first result does not match the prediction.`,
          known:`The source or input, stated configuration, expected relationship, instrument or observation method, and acceptance boundary are available. The exact cause is not known.`,
          reasoning:`First freeze the configuration and establish the expected chain. Separate at least two plausible causes. Predict a different observation for each cause, then choose the safest test that creates the most information. Keep units, logic levels, timing, revision, and virtual/physical limits explicit.`,
          work:`1. Draw or list the input-to-output path. 2. Mark the last confirmed-good boundary. 3. State two hypotheses and their predicted signatures. 4. Perform one discriminating calculation, code trace, inspection, or measurement. 5. Compare the observation with both predictions. 6. Correct only the supported cause. 7. Repeat the original test and one boundary/recovery test.`,
          result:`The conclusion is the cause supported by the discriminating evidence, not merely the component or line changed last. The record links the correction to the restored requirement.`,
          sanity:`Ask whether an unchanged subsystem was retested, whether the result could be explained by loading, units, configuration, or stale code, and whether a second person could reproduce the finding.`,
          interpretation:`This reasoning pattern is reusable on CETa scenarios, bench circuits, instruments, firmware, interfaces, test automation, and technical interviews.`
        },
        misconceptions:model.faults.map((fault,i) => ({mistake:fault,why:`This is tempting because it produces a fast-looking answer or action while hiding an assumption. In ${model.name}, that shortcut collapses distinct quantities, layers, states, or evidence types.`,repair:`Return to the labeled model and make one prediction that would differ if the shortcut were true. Use the ${i===0?'physical relationship':i===1?'units, ratings, or representation':'safe evidence and verification chain'} to choose the correct interpretation.`})),
        guidedPractice:[
          `With the lesson visible, annotate the central model for “${firstObjective}.” Label inputs, outputs, reference, units or representation, assumptions, and one stop condition.`,
          `Complete the original worked example, but pause before every step and state why that law, setting, data transformation, or test is valid. Change one value or condition and predict what must change.`,
          `Create two competing explanations for one of these failure modes: ${model.faults.join('; ')}. Write the observation that would support each and select one safe discriminating test.`,
          `Use the exact competency clinic below. For each assigned row, underline the action verb, explain the requirement in plain language, give one real example, and state what evidence would count.`
        ],
        independentTransfer:`Close the lesson and complete a changed problem or scenario using a different value, component, input, fault, circuit, code path, or role context. Produce the diagram or model, prediction, work, evidence, diagnosis, and retest without copying the worked example. Then compare your reasoning with the lesson and write the smallest correction needed.`,
        technicianConnection:`In electronics/test work, ${model.name} appears through schematics, datasheets, PCBs, instruments, fixtures, firmware, interfaces, procedures, and failure reports. The technician or embedded engineer is expected to identify the boundary, predict behavior, make a safe observation, avoid overstating the result, and hand off a traceable record. This lesson’s artifact can support a portfolio claim only when you personally understand and can defend it.`,
        troubleshooting:`Use Expected → Observed → Hypotheses → Discriminating test → Diagnosis → Corrective action → Verification. Expected: state the value, waveform, logic state, message, build result, timing, physical condition, or document outcome with its tolerance. Observed: preserve the raw evidence and settings. Hypotheses: include at least one setup/configuration cause and one device/circuit/code cause. Test: choose one safe action whose outcomes differ. Diagnosis: cite the evidence. Correction: change one supported cause. Verification: repeat the original test, a boundary case, and safe recovery where applicable.`,
        teachBack:`In two minutes, teach ${lesson.title.toLowerCase()} to a new student without reading. Define the central quantities or states, draw the system, explain one relationship or calculation, describe one common mistake, choose one safe measurement or test, and state what evidence would prove understanding. If the explanation depends on “because the formula says so” or “because the tutorial did it,” return to the physical mechanism.`,
        coverage:trackRows.map(row => ({code:row.code,officialRequirement:row.text,category:row.category,categoryTitle:row.categoryTitle,teachingSection:`${sectionId} · Competency clinic`,teachingLevel:'Explain → practice → transfer → assess → retain'}))
      };

      trackRows.forEach(row => allCoverage.push({
        track:row.track,code:row.code,officialRequirement:row.text,category:row.category,categoryTitle:row.categoryTitle,
        week:module.week,lesson:lesson.title,teachingSection:`${sectionId} · Competency clinic`,teachingLevel:'Alfred-authored explanation with mechanism, distinction, example, misconception, and evidence rule',
        guidedPractice:`Underline the action verb; explain ${row.code} in plain language; give a circuit, instrument, component, code, procedure, or work example; then state valid evidence.`,
        independentPractice:`Apply ${row.code} in a changed scenario without notes and distinguish the correct reasoning from one plausible shortcut.`,
        assessmentEvidence:`Current reviewed question mapped to ${row.id}; in-lesson knowledge check; Week ${module.week} mastery/teach-back.`,
        masteryEvidence:`Correct retrieval, changed-context transfer, explanation of the tempting error, and later cumulative/retention evidence; safety-critical work also requires the stated perfect check.`,
        laboratoryEvidence:module.integration.labId ? `${module.integration.labId}: ${module.integration.evidence} Physical proficiency is credited only on the physical route.` : `Week ${module.week} project/application evidence: ${module.integration.evidence}`,
        labId:module.integration.labId || ''
      }));
    });
    module.instructionalCoverage = {
      ceta:allCoverage.filter(r => r.week===module.week && r.track==='CETa').map(r=>r.code),
      career:allCoverage.filter(r => r.week===module.week && r.track==='Career').map(r=>r.code)
    };
  });

  // Explicit C1.6 repair: no test may continue until the hazard and correction
  // are recorded and the safe condition is independently verified.
  const week1Career = C.modules.find(m=>m.week===1)?.lessons.find(l=>l.track==='Career');
  if (week1Career && !week1Career.sections.some(s=>/hazard log/i.test(s.title))) week1Career.sections.push({
    title:'Hazard log before continuing a test',
    teach:'When inspection or a measurement exposes a wrong polarity, damaged lead, unexpected current, missing ground, loose conductor, excessive temperature, unsuitable source, or other setup hazard, stop and de-energize. Record the condition and location, the credible consequence, the immediate control, the corrective action, and the verification result. A different person should be able to tell what was unsafe and why testing was allowed to resume. Do not erase the original observation or write the log after continuing; traceability is part of the safety control. Resume only after the safe state is confirmed and any required authorization is obtained.',
    remember:'Find hazard → stop/de-energize → record condition and risk → correct → independently verify → authorize → continue. Silence is not a corrective action.',
    critical:true
  });

  // Week 18 is one cumulative demonstration, not a collection of old checks.
  const w18 = C.modules.find(m=>m.week===18);
  if (w18) w18.integration = {
    ...w18.integration,
    title:'Cumulative Embedded Gate · STM32 → SWD → UART → I²C/SPI → Logic Analysis → Fault Report',
    brief:'This is one integrated demonstration, not a collection of earlier checkboxes. Start from the STM32 project configuration and a known-good baseline, build and flash the image, prove program flow through SWD, log a milestone over UART, integrate one I²C or SPI peripheral, capture and interpret the transaction, inject one safe reversible fault, diagnose it with evidence, correct it, rerun nominal and recovery tests, and publish the setup/result record. Virtual evidence is valid for academic reasoning; physical probe or wiring claims require the physical route.',
    guided:[
      'Create a controlled STM32 baseline: board/revision, clock, pin mux, build result, firmware revision, and recovery path.',
      'Build and flash; use SWD/debug to verify reset, program flow, and at least one breakpoint, variable, memory, or register observation.',
      'Use UART for a timestamped bring-up log, then connect one I²C or SPI peripheral from its datasheet and prove identity/register data.',
      'Capture the bus with a logic analyzer; label wiring, voltage, sample rate/threshold, address or chip-select, command, expected bytes, and raw/decoded evidence.',
      'Insert one safe reversible wrong-address, disconnect, or configuration fault. Show prediction, detection, diagnosis, correction, nominal retest, recovery retest, and technical report.'
    ],
    independent:'Defend the entire chain to a cold reviewer using only the report and raw evidence. The reviewer must identify the first failed boundary, why the selected measurement separated the leading hypotheses, and how the retest proves both normal operation and fault recovery.',
    evidence:'One cumulative gate packet: project configuration/build/flash record; SWD observation; UART log; schematic/wiring and datasheet trace; raw and decoded I²C/SPI capture; controlled fault insertion; hypothesis/measurement/cause/corrective-action chain; nominal and recovery retest; limitations; and teach-back. Label the virtual or physical route on every claim.',
    labId:'LAB-018',
    practiceCheck:'In one minute, explain what evidence distinguishes a power/reset failure, an SWD/flash failure, a UART configuration failure, a bus wiring/pull-up/mode failure, and a firmware/register failure before changing anything.'
  };

  C.coverageMatrix = allCoverage;
  C.meta = {...C.meta,version:'16.1',updated:'2026-09-15',instructionalDepthPolicy:'All 62 primary lessons include purpose, prerequisites, Alfred-authored teaching, worked reasoning, misconceptions, guided practice, independent transfer, technician connection, troubleshooting, knowledge check, teach-back, and exact row traceability.',coveragePolicy:'Every current official CETa and Alfred career row maps to an exact in-house teaching section, practice, assessment, mastery, and practical route.',coverageCounts:{ceta:allCoverage.filter(r=>r.track==='CETa').length,career:allCoverage.filter(r=>r.track==='Career').length,total:allCoverage.length}};
  window.ALFRED_INSTRUCTIONAL_COMPLETION = {version:'16.1',coverage:allCoverage,home};
})();
